using System.IO;
using System.Text.Json;
using System.Windows;
using VisionFramework;
using VisionPluginContracts;
using VisionPlugins.Calibration;
static class Program{
 static int checks;static JsonElement J<T>(T x)=>JsonSerializer.SerializeToElement(x);static void Check(bool c,string m){if(!c)throw new Exception(m);checks++;}
 static readonly string[] Names=["CalibPointTotalNum","RotPointTotalNum","UnionCalibEnable","TeachEnable","RefreshFileEnable","CalibPathName"];
 static readonly Dictionary<string,int> Defaults=new(){["HomoFreedom"]=2,["WeightFun"]=3,["WeightFactor"]=20,["DistThreshold"]=30,["SampleRatio"]=60,["CameraMode"]=1};
 [STAThread]static int Main(){try{_=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Scenario(false);Scenario(true);Console.WriteLine($"PASS {checks} Translation source8-default/6ISub reset checks");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Scenario(bool reject){var plugin=new TranslationPlugin();var values=plugin.Descriptor.Parameters.ToDictionary(p=>p.Name,p=>p.DefaultValue!.Value.Clone());values["CalibType"]=J(1);values["UnionCalibEnable"]=J(true);values["WeightFun"]=J(1);values["WeightFactor"]=J(75);values["DistThreshold"]=J(80);values["SampleRatio"]=J(90);values["HomoFreedom"]=J(3);values["CameraMode"]=J(2);values["ImagePointX0"]=J(12.25);values["WorldPointY31"]=J(72.5);values["CalibPointGet"]=J(1);values["RotPointTotalNum"]=J(0);values["CalibPathName"]=J(Path.GetFullPath("analysis/translation/keep.xml"));values["RefreshFileEnable"]=J(false);values["DisplaySettings"]=J("");values["ConfigurationUserData"]=J(JsonSerializer.Serialize(Names.ToDictionary(n=>"@"+n,_=>"True").Concat(new[]{new KeyValuePair<string,string>("Keep","value")}).ToDictionary(p=>p.Key,p=>p.Value)));var subs=new Subs();var confirm=new Confirms();var notices=new Notices();int atomic=0,runs=0;bool record=false;var writes=new List<string>();
 IReadOnlyDictionary<string,JsonElement> Effective()=>new Dictionary<string,JsonElement>(values);
 var context=new ToolEditorContext(new("reset",TranslationPlugin.Id,"1.0.0","Translation",values),Environment.CurrentDirectory,next=>{if(record)writes.AddRange(next.Where(p=>p.Key!="ConfigurationUserData"&&values[p.Key].GetRawText()!=p.Value.GetRawText()).Select(p=>p.Key));if(record&&reject&&next["WeightFactor"].GetInt32()==20&&values["WeightFactor"].GetInt32()==75)throw new InvalidOperationException("reject hidden WeightFactor");values=next;},_=>{runs++;throw new Exception("must not run");}){ReadEffectiveParameters=Effective,ConfigurationSubscriptions=subs,ConfigurationConfirmations=confirm,ConfigurationNotifications=notices,ResetConfigurationParameters=_=>{atomic++;throw new Exception("no atomic");}};
 using var session=plugin.CreateConfiguration(context);var state=session.State;Check(new[]{"WeightFun","WeightFactor","DistThreshold","SampleRatio"}.All(n=>state.Find(n)is null),"four backend defaults have no fabricated UI nodes");
 foreach(string name in Names){var node=state.Find(name)!;var kind=plugin.Descriptor.Parameters.Single(p=>p.Name==name).Kind;var type=kind==ParameterKind.Text?"string":kind==ParameterKind.Number?"float":"int";subs.Bound[name]=new(new ConfigurationConstantReference(type,"1"),ConfigurationSubscriptionIndex.All);state.ApplySubscription(node,subs.Read(new(ConfigurationSubscriptionDomain.Parameter,name,type)),true);}
 subs.Clears.Clear();var before=values.ToDictionary(p=>p.Key,p=>p.Value.GetRawText());confirm.Allow=false;state.Invoke(state.Find("Button_ResetAlgoParams")!);Check(subs.Clears.Count==0&&before.All(p=>values[p.Key].GetRawText()==p.Value),"cancel no mutation");confirm.Allow=true;record=true;state.Invoke(state.Find("Button_ResetAlgoParams")!);record=false;
 Check(subs.Clears.SequenceEqual(Names),"6 source ISUB order including persisted-only modes: "+string.Join(",",subs.Clears));Check(atomic==0&&runs==0,"reset neither atomic nor run");Check(writes.SequenceEqual(new[]{"HomoFreedom","WeightFun","WeightFactor","DistThreshold","SampleRatio","CameraMode","CalibType","RefreshFileEnable"}),"all eight backend writes follow original order including hidden defaults and rejection continuation");foreach(var p in Defaults)Check(values[p.Key].GetInt32()==(reject&&p.Key=="WeightFactor"?75:p.Value),"default "+p.Key);Check(values["CalibType"].GetInt32()==0&&values["RefreshFileEnable"].GetBoolean(),"source-only defaults include CalibType0 and RefreshTrue");foreach(string name in new[]{"ImagePointX0","WorldPointY31","CalibPointGet","RotPointTotalNum","CalibPathName","UnionCalibEnable","DisplaySettings"})Check(values[name].GetRawText()==before[name],"non-list preserved "+name);var user=JsonSerializer.Deserialize<Dictionary<string,string>>(values["ConfigurationUserData"].GetString()!)!;Check(Names.All(n=>user["@"+n]=="False")&&user["Keep"]=="value","persist modes false preserve unknown");Check(notices.Items.Last().Kind==(reject?ConfigurationNotificationKind.Error:ConfigurationNotificationKind.Success),"final notification matches write result");}
 sealed class Subs:IToolConfigurationSubscriptionService{public Dictionary<string,ConfigurationSubscriptionBinding> Bound=[];public List<string> Clears=[];public ConfigurationSubscriptionTreeResult Enumerate(ConfigurationSubscriptionQuery q)=>new(ConfigurationSubscriptionStatus.Available,[]);public ConfigurationSubscriptionBindingResult Read(ConfigurationSubscriptionDestination d)=>new(ConfigurationSubscriptionStatus.Available,Bound.GetValueOrDefault(d.Name),Bound.ContainsKey(d.Name)?"1":"");public ConfigurationSubscriptionBindingResult Bind(ConfigurationSubscriptionDestination d,ConfigurationSubscriptionBinding? b){if(b is null){Clears.Add(d.Name);Bound.Remove(d.Name);}else Bound[d.Name]=b;return Read(d);}}
 sealed class Confirms:IToolConfigurationConfirmationService{public bool Allow;public bool Confirm(Window? w,ConfigurationConfirmation r)=>Allow;}
 sealed class Notices:IToolConfigurationNotificationService{public List<ConfigurationNotification> Items=[];public ConfigurationNotificationResult Notify(Window? w,ConfigurationNotification n){Items.Add(n);return new(ConfigurationNotificationStatus.Displayed);}}
}
